INSERT INTO evaluation_criteria (code, name, standard_id, description, complexity, is_mandatory) VALUES
('TSTH-001', '1. El talento humano en salud y otros profesionales que se relacionan con la atención o resultados en salud de los usuarios, cuentan con los titulos, según aplique, de educación superior o certificados de aptitud ocupacional, expedidos por la entidad educ', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-002', '2. El talento humano en salud cuenta con copia de la resolución de autorización del ejercicio expedido por la autoridad competente  o inscripción e en el ReTHUS', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-003', '3. El prestador de servicios de salud determina la cantidad necesaria de talento humano requerido para cada uno de los servicios ofertados y prestados, de acuerdo con la capacidad instalada, la relación entre la oferta y demanda, la oportunidad en la pres', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-004', '4. El prestador de servicios de salud que actúe como escenario de práctica formativa en el área de la salud, cuenta con:', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'simple', true),
('TSTH-005', '4.1. Convenio vigente con la institución educativa autorizada por la entidad competente', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'simple', true),
('TSTH-006', '4.2. Información documentada de los mecanismos de supervisión permanente del personal en entrnamiento', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'simple', true),
('TSTH-007', '4.3. Estudio de la capacidad instalada en el cual se dtermine el número máximo de estudiantes que simultaneamente puedan acceder por programa de formación y por jornada, para cada uno de los servicios que se utilicen como escenarios de práctica formativa ', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-008', '5. En los servicios de salud diferentes a los servicios de consulta externa especializada de dolor y cuidado paliativo, donde se atienden pacientes con enfermedades terminales, crónicas, degenerativas e irreversibles, a los cuales se les decida como condu', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-009', '6. El talento humano en salud de los servicios de atención del parto, cuidado intensivo y cuidado intermedio neonatal, pediátrico y adultos, cuentan con constancia de asistencia en las acciones de formación continua para la gestión del duelo', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-010', '7. En los servicios de salud donde se realicen imagenes diagnósticas por ultrasonido, cuenta con médico especialista en radiologia e imagenes diagnósticas también podrán realizar imagenes diagnósticas aquellos médicos especialistas, quienes en su pensum o', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-011', '8. Los profesionales de la medicina de los servicios de hospitalización de baja, mediana y alta complejidad, hospitalización paciente crónico con y sin ventilador, cuidados intensivos neonatales, pediátricos y adultos; urgencias, y servicios del grupo qui', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-012', '9. Las instituciones prestadoras de servicios de salud con servicios de cuidado intensivo pediatrico y adulto que adicionalmente habiliten servicio quirurgico de neurocirugía, tienen disponibilidad de coordinador operativo de trasplantes.', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-013', '10. El talento humano en salud de los servicios de salud de los grupos de consulta externa, internación y el servicio de urgencias, cuentan con constancia de asistencia en las acciones de formación continua en la atención integral en salud de las personas', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-014', '11. El talento humano en salud de los servicios de transporte asistencial, atención prehospitalaria y urgencias, cuentasn con constancia de asistencia en las acciones de formación continua en la atención a personas víctimas de ataques con agentes químicos', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-015', '12. Cuando en un servicio de salud se realicen "pruebas en punto de atención del paciente - (point of care testing - POCT)", el talento humano en salud qeu las realice, a excepción del profesional en bacteriologia cuenta con constancia de asistencia en la', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-016', '13. Procedimientos bajo sedación:', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'simple', true),
('TSTH-017', '13.1 Cuando fuera de salas de cirugía, se realicen procedimientos bajo sedación Grado I y II, adicional al profesional de salud que realiza el procedimiento, cuenta con:', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-018', '13.1.1. Profesional en la medicina especialista en anestesiologia, o profesional de la medicina o profesional en odontologia, según aplique, el cual será el encargado de administrar el medicamento y realizar el monitoreo continuo del paciente (registro de', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-019', '13.1.2. Todos los profesionales, a excepción del profesional de la medicina especialista en anestesiologia, deben demostrar constancia de asistencia a curso de formación continua en soporte vital básico y sedación', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-020', '13.1.3 Para sedacción con óxido nitroso en odontologia, el profesional de la odontología cuenta con constancia de asistencia en las acciones de formación continua para uso clínico y práctico de este gas.', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'medium', true),
('TSTH-021', '13.2. Cuando fuera de las salas de cirugia, se realicen procedimientos bajo sedación grado III, adicional al profesional de salud que realiza el procedimiento, cuenta con profesional de la medicina con especialidad médico - quirúrgica, quién será el respo', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-022', '13.3. Cuando fuera de las salas de cirugía, se realicen procedimientos bajo sedación grado IV, adicional al profesional de  salud que realiza el procedimiento, cuenta con profesional de la medicina especialisa en anestesiologia, quién será el responsable ', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-023', '13.4 Cuenta con profesional de la medicina especialista en anestesiologia cuando la atención de trate de pacientes con caracteristicas particulares: poco colaboradores; edades extremas; con enfermedades severas:cardíacas, pulmonares, hepáticas, renales o ', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSTH-024', 'Modalidad de telemedicina prestador remisor - prestador de referencia', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'simple', true),
('TSTH-025', '14. Adicional a los criterios del estándar de talento humano enunciados que le aplique, el talento humano en salud que preste directamente un servicio de salud bajo la modalidad telemedicina cuentan con constancia de asistencia en las acciones de formació', '5f7bdc62-9c2a-4579-9cee-4f4766beb838', 'Talento Humano', 'complex', true),
('TSINF-001', 'Edificaciones de uso exclusivo en salud', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-002', '1. Los servicios de salud de urgencias, de atención del parto, hospitalarios y de cirugía que realicen procedimientos quirúrgicos no ambulatorios, solo se pueden prestar en edificaciones de uso exclusivo de salud.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-003', '2. Los servicios de salud de: urgencias, cirugía y del grupo de internación, así como en los servicios de salud donde se realice el proceso de esterilización, deben contar con ambiente de aseo de uso exclusivo', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-004', '3. Cuando en una edificación de uso exclusivo de salud funcione más de un prestador de servicios de salud con servicios de los grupos de consulta externa y apoyo diagnóstico y complementación terapeutica, cada prestador cuenta con infraestructura separada', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-005', '4. Las edificaciones donde se presten servicios de salud de urgencias y del grupo de internación, cuentan con tanque de almacenamientode agua para el consumo humano que garantice como mínimo una reserva de 24 horas de servicio continuo, calculando con bas', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-006', '5. Cuando el prestador de servicios de salud cuente con mas de una infraestructura y estas se puedan vincular funcionalmente entre si, lo harán mediante tunel o puente cubierto, o muro(s) colindante(s) que cuenten con acceso (s) que intercomuniquen las in', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-007', '5.1. Ancho que permita la movilización de camas, camillas, sillas de ruedas, equipos biomédicos  y personal para el traslado de los pacientes  en condiciones seguras.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-008', '5.2. El piso del túnel o puente debe ser uniforme y de material antideslizante o con elementos que garanticen esta propiedad en todo su recorrido, con pasamanos d a ambos lados y con protecciones laterales hacia espacios libres.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-009', '5.3. Lo anterior siempre y cuando la norma urbanística de la jurisdicción donde se localizan las sedes hayan aprobado esta forma de vinculación funcional entre las mismas.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-010', '5.4. Esta edificación se podrá habilitar como una o varias sedes, de acuerdo con lo que determine el prestador de servicios de salud', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-011', 'Edificaciones de uso mixto', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-012', '6. Cuando en una edificación de uso mixto funcione más de un prestador de servicios de salud, cada uno cuenta con infraestructura separada y delimitada físicamente. Se pueden compartir las salas de espera y las unidades sanitarias.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-013', '7. En edificaciones de uso mixto pueden funsionar los prestadores de servicios de salud que oferten y presten servicios de los grupos de consulta externa. de apoyo diagnóstico y complementación terapeutica y los servicios del grupo quirurgico que realicen', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-014', 'Edificaciones de uso exclusivo en salud y edificaciones de uso mixto', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-015', '8. Los prestadores de servicios de salud ubicados en edificaciones de hasta tres (3) pisos o niveles contados a partir del nivel más bajo construido, y que funcione en segundo o tercer nivel o piso, cuentan con ascensor o rampa o sistema alternativo de el', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-016', '9. Los sistemas alternativos de elevación deben cumplir con las siguientes condiciones:', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-017', '9.1. Su ubicación no interfiera con el acceso y evacuación de los usuarios por las escaleras', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-018', '9.2. Estén disponibles tanto para el acceso como para la evacuación de los usuarios', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-019', '9.3. Su manejo sea autonomo', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-020', '9.4. Garanticen seguridad durante su uso', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-021', '10. Las edificaciones con más de tres (3) pisos o niveles, contados a partir del nivel más bajo construido, cuentan con ascensor.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-022', '11. En edificaciones donde se presten servicios de los grupos de internación, atención del parto, quirurgicos o urgencias para la movilización de pacientes en camilla, la cabina de los ascensores debe tener las dimensiones interiores mínimas de 2.20 de pr', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-023', '12. Si se tienen escaleras o rampas, el piso debe ser uniforme y de material antideslizante o con elementos que garanticen esta propiedad en todo su recorrido, con pasamanos de preferencia a ambos lados y con protecciones laterales hacia espacios libres.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-024', '13. Las edificaciones donde se presten servicios de salud cuentan con suministro de agua, energia eléctrica, conexión a la red de alcantarillado y sistemas de comunicaciones.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-025', '14. En edificaciones donde se presten servicios de cirugía, atención del parto, laboratorio clínico, urgencias, gestión pre transfusional, dialisis, hospitalarios, imagénes diagnósticas, vacunación, servicio farmaceutico y los que requieran cadena de frio', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-026', '15. El prestador de servicios de salud que utilice equipos generadores de radiaciones ionizantes cuenta con licencia de práctica médica vigente expedida por la entidad competente.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-027', '16. El prestador de servicios de salud que utilice fuentes radiactivas cuenta con autorización vigente de empleo de material radiactivo, expedida por la entidad reguladora competente', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-028', '17. Cada prestador de servicios de salud debe contar con el respectivo concepto sanitario que dé cumplimiento a lo establecido en la normatividad sanitaria vigente en aspectos tales como agua para consumo humano, gestión de residuos, control de vectores, ', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-029', 'Generalidades de los ambientes y las áreas de los servicios y sus características', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-030', '18. Las áreas y ambientes de todos los servicios de salud cuentan con ventilación natural o artificial.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-031', '19. Las áreas de circulación están libres de obstáculos de manera que permitan la movilización de pacientes, talento humano, usuarios y equipos biomédicos', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-032', '20. Los ambientes y áreas que hagan parte de cualquier servicio de salud, deben permitir la instalación y movilización de equipos biomedicos y personal necesarios para la atención del paciente en condiciones de rutina o de emergencia.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-033', '21.En los servicios del grupo quirurgico, los ambientes y áreas clasificados como no restringidos, semirestringidos, deben señalizarse mediante la demarcación permanente en piso con material lavable y resistente al tráfico pesado, utilizando los siguiente', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-034', '21.1. Verde: Ambientes o áreas no restringidas', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-035', '21.2. Amarillo: Ambientes o áreas semi-restringidas', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-036', '21.3. Roja: Ambientes o áreas restringidas', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-037', '22. Cada uno de los pisos o niveles de la edificación cuenta con señalización y planos indicativos de las rutas de evacuación, salidas de emergencia y puntos de encuentro, visible al público en general.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-038', '23. Si el prestador de servicios de salud no tiene habilitado el servicio de gestión pre-transfusional, pero realiza procedimientos de transfusión sanguínea en alguno de sus servicios habilitados, tiene disponibilidad de un área con iluminación y ventilac', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'complex', true),
('TSINF-039', '24. Cuando un prestador de servicios de salud realice procedimientos bajo sedación fuera de salas de cirugía, tiene disponibilidad de área o ambiente para la recuperación de pacientes que puede ser la misma área o ambiente donde se realiza el procedimient', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-040', '25. El prestador de servicios de salud que realice el proceso de esterilización, cuenta con:', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-041', '25.1. Ambiente o área de recibo de material contaminado.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-042', '25.2. Ambiente o área de lavado', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-043', '25.3. Ambiente o área de secado', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-044', '25.4. Ambiente o área de empaque.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-045', '25.5. Ambiente o área de esterilización', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-046', '25.6. Ambiente o área para almacenamiento de material esteril', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-047', '25.7. Mesón de trabajo con poceta', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-048', '25.8. Lavamanos, cuando el proceso se realice fuera del servicio de salud', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-049', '26. El prestador de servicios de salud que contrate el proceso de esterilización, dentro de su infraestructura cuenta con:', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-050', '26.1. Ambiente o área para lavado, limpieza y desinfección y entrega de material limpio al proveedor', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-051', '26.2.  Ambiente o área para la recepción y almacenamiento del material esteril', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-052', '27. El prestador de servicios de salud que realice el proceso de esterilización en una cetral de esterilización cuenta con los siguientes ambientes y áreas señalizadas unidireccionales y de circulación restringida.', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'medium', true),
('TSINF-053', '27.1. Ambiente de recibo y lavado de material contaminado', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-054', '27.2. Ambiente limpio con las siguientes áreas:', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-055', '27.2.1. Área de secado', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-056', '27.2.2. Área de empaque', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-057', '27.2.3. Área de esterilización', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-058', '27.3. Ambiente para almacenamiento de material esteril', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-059', 'Caracteristicas de los ambientes y áreas que pueden ser requeridos en varios servicios de salud', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
('TSINF-060', '28. Consultorio: para efectos del presente manual se definen los siguientes tipos de consultorios de acuerdo con la oferta de servicios:', 'f02f29be-b9b5-477c-b57d-a80d04182f8e', 'Información', 'simple', true),
